# whole-picture styles (the page picture with the Japanese cleared and the English set in it)
def _pic(comp, c0, c1, box, dy, front):
    comp = np.array(comp, np.uint8)
    bx0, by0, bx1, by1 = box
    def style(ink, base):
        art, _ = STYLES[front](ink, base)
        h, w = art.shape
        out = comp.copy()
        ox = bx0 + (bx1 - bx0 - w) // 2; oy = by0 + (by1 - by0 - h) // 2 + dy
        m = art > 0
        out[oy:oy + h, ox:ox + w][m] = art[m]
        return out[:, c0:c1], 0
    return style
